pm.test("Invalid email update returns 400 Bad Request", () => {
    pm.response.to.have.status(400);
});

pm.test("Error message identifies invalid email", () => {
    const response = pm.response.json();
    pm.expect(response.message).to.eql(
        "Please provide a valid email address."
    );
});

pm.test("Successful update returns 200 OK", () => {
    pm.response.to.have.status(200);
});

const student = pm.response.json();

pm.test("First name was updated", () => {
    pm.expect(student.firstName).to.eql("John Updated");
});

pm.test("City was updated", () => {
    pm.expect(student.nearCity).to.eql("Colombo");
});

pm.test("Student ID remains unchanged", () => {
    pm.expect(student.SID).to.eql(Number(pm.collectionVariables.get("__smsRunGeneratedStudentSID")));
});

pm.test("Unmodified email remains unchanged", () => {
    pm.expect(student.email).to.eql("john@example.com");
});

pm.test("Non-existent student returns 404 Not Found", () => {
    pm.response.to.have.status(404);
});

pm.test("Error message identifies the missing student", () => {
    const response = pm.response.json();
    pm.expect(response.message).to.eql("Student not found.");
});

